# -*- coding: utf-8 -*-
"""
BÀI SÁP NHẬP V4.5.2 - CHUẨN HÓA TÊN GIAO DIỆN

Mục tiêu nội bộ:
- Bỏ số phiên bản khỏi toàn bộ giao diện sáp nhập.
- Giữ nguyên chức năng Đổi tên trường.
- Không thay đổi nghiệp vụ sáp nhập, không thực hiện sáp nhập.
- Không chủ động ghi phocap.db.
"""
from __future__ import annotations
import base64, datetime as dt, hashlib, json, os, py_compile, re, shutil, traceback
from pathlib import Path

TITLE = "BÀI SÁP NHẬP V4.5.2 - CHUẨN HÓA TÊN GIAO DIỆN"
EMBEDDED_FILES = {'app/templates/data_tools/school_merger.html': '', 'app/templates/data_tools/school_merger_dashboard_v45.html': '', 'app/templates/data_tools/school_merger_future_v45.html': '', 'app/templates/data_tools/school_merger_future_preview_v45.html': '', 'app/templates/data_tools/school_merger_future_result_v45.html': '', 'app/templates/data_tools/school_merger_plans.html': '', 'app/templates/data_tools/school_merger_result.html': '', 'app/services/school_merger_future_service.py': '', 'app/routers/school_merger_future.py': ''}
EXPECTED_BASE_HASHES = {'app/templates/data_tools/school_merger.html': '8b8c5fbf899755056fcdfcfc91d1247049ca92163a2c1e5e8e1573cf5ebf833d', 'app/templates/data_tools/school_merger_dashboard_v45.html': '9d6aed17afc023bae4031a400e38550ea3d1765ea3bedded129e1a1ae18e8697', 'app/templates/data_tools/school_merger_future_v45.html': 'a37b7e2b3676ccec0ebfaa3deac3b07b7003d0412213528e99ce344f805e5bfa', 'app/templates/data_tools/school_merger_future_preview_v45.html': '194e13ff108865250862e43074b4109cb6b3ff12a0f6342068e9e460e05315d7', 'app/templates/data_tools/school_merger_future_result_v45.html': '109b5560a375237e84e32dfcb462c5be390e2e2523131423adbe11f510564281', 'app/templates/data_tools/school_merger_plans.html': '6ff302aa3f8ced8d3e07db9dd473d74b2caad551ccc7cd6ec1472c02bdcdce3b', 'app/templates/data_tools/school_merger_result.html': '7f70a34ec2bd5dd551cd7bdd14914aa89f1ac3bea21bcab038aa5aab743d39b5', 'app/services/school_merger_future_service.py': '919826a8caf87563a5d98343a69acafffd4b4e588ae510c565955cf309aed4c8', 'app/routers/school_merger_future.py': '4995f619f1b7424a16d440f0d8244430525182e3cc149d3909f56540d3e6f870'}
FINAL_HASHES = {'app/templates/data_tools/school_merger.html': 'f52cde2f6fb7f34c279f9b746113a5e6fd711e0fc902cf55acd533f3a34072b3', 'app/templates/data_tools/school_merger_dashboard_v45.html': '327a8326ac11fe24740faabf0be0f02698ca48735d3df695fc54f3d60f30927e', 'app/templates/data_tools/school_merger_future_v45.html': 'a99d32bca310279ed578a1e33c468dcc4451f38a55aaf4f7c7f1785ba5def901', 'app/templates/data_tools/school_merger_future_preview_v45.html': '229c887e3cf0efb5244b7731fdd2c657f4eafa7fc71880614fc473930ed20a7b', 'app/templates/data_tools/school_merger_future_result_v45.html': '839f86fa1459ebc847975e285ae75ca4d6462b4250879e9e5ec5031196ba6e06', 'app/templates/data_tools/school_merger_plans.html': '6b8eb30fee5f4c3a248a445395c237cde3e1d34f86c268f6471f6e7eff2b5f81', 'app/templates/data_tools/school_merger_result.html': 'f18cdedac9b110c555f345dfb8cfd06089af1d9068d18a06798febe808f6e6fd', 'app/services/school_merger_future_service.py': '528a337f91f687d257ea4e2eaf1fd84395e472e025617b8a3ccab0dcd88963b3', 'app/routers/school_merger_future.py': 'e7ddc112a0198c61b58610a58b2d4b75243111e91a626f3ad52bb94bdea61d91'}

def sha256_file(p: Path) -> str:
    h = hashlib.sha256()
    with p.open("rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()

def db_fingerprint(db: Path) -> str:
    h = hashlib.sha256()
    for p in [db, Path(str(db)+"-wal"), Path(str(db)+"-shm")]:
        h.update(p.name.encode("utf-8"))
        if p.exists():
            h.update(str(p.stat().st_size).encode("ascii"))
            h.update(sha256_file(p).encode("ascii"))
        else:
            h.update(b"MISSING")
    return h.hexdigest()

def fail(msg: str):
    raise RuntimeError(msg)

def main():
    cwd = Path.cwd().resolve()
    script_dir = Path(__file__).resolve().parent
    root = cwd if (cwd / "app").exists() else script_dir
    if not (root / "app").exists():
        fail(r"Không tìm thấy thư mục app. Hãy chép bộ cài vào C:\PhoCap và chạy tại C:\PhoCap.")
    db = root / "data" / "phocap.db"
    if not db.exists():
        fail(f"Không tìm thấy database: {db}")

    ts = dt.datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_dir = root / "backups" / f"backup_truoc_chuan_hoa_ui_sap_nhap_{ts}"
    export_dir = root / "exports" / "Chuan_Hoa_Giao_Dien_Sap_Nhap"
    report_path = export_dir / f"bao_cao_{ts}.json"
    db_before = db_fingerprint(db)
    touched = []
    try:
        for rel in EMBEDDED_FILES:
            p = root / rel
            if not p.exists():
                fail(f"Thiếu tệp nền: {rel}")
            cur = sha256_file(p)
            if cur not in {EXPECTED_BASE_HASHES[rel], FINAL_HASHES[rel]}:
                fail(f"Tệp {rel} không đúng nền đã khóa. SHA hiện tại={cur}")

        backup_dir.mkdir(parents=True, exist_ok=True)
        for rel in EMBEDDED_FILES:
            src = root / rel
            dst = backup_dir / rel
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)

        for rel, b64 in EMBEDDED_FILES.items():
            p = root / rel
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_bytes(base64.b64decode(b64))
            touched.append(rel)

        for rel, expected_hash in FINAL_HASHES.items():
            got = sha256_file(root / rel)
            if got != expected_hash:
                fail(f"SHA sau cài không đúng: {rel}")

        py_compile.compile(str(root / "app/routers/school_merger_future.py"), doraise=True)
        py_compile.compile(str(root / "app/services/school_merger_future_service.py"), doraise=True)

        templates = list((root / "app/templates/data_tools").glob("school_merger*.html"))
        ui_text = "\n".join(p.read_text(encoding="utf-8") for p in templates)
        if re.search(r"V\d+(?:\.\d+)+|Bài V\d+", ui_text):
            fail("Vẫn còn số phiên bản trên giao diện sáp nhập.")
        outer = (root / "app/templates/data_tools/school_merger.html").read_text(encoding="utf-8")
        dashboard = (root / "app/templates/data_tools/school_merger_dashboard_v45.html").read_text(encoding="utf-8")
        future = (root / "app/templates/data_tools/school_merger_future_v45.html").read_text(encoding="utf-8")
        if "Đổi tên trường" not in outer:
            fail("Chức năng Đổi tên trường bị mất khỏi màn hình Sáp nhập trường.")
        if "SÁP NHẬP PHÁT SINH" in outer:
            fail("Sáp nhập phát sinh vẫn còn lặp ở màn hình ngoài.")
        if "SÁP NHẬP PHÁT SINH" not in dashboard:
            fail("Bảng điều khiển bị mất nút Sáp nhập phát sinh.")
        for needle in ["BƯỚC 1", "Xã/phường", "BƯỚC 2", "Cấp học", "BƯỚC 3", "Năm hiệu lực", "NẠP DANH SÁCH TRƯỜNG", "TRƯỜNG NGUỒN", "TRƯỜNG ĐÍCH"]:
            if needle not in future:
                fail(f"Thiếu thành phần luồng sáp nhập phát sinh: {needle}")

        db_after = db_fingerprint(db)
        if db_after != db_before:
            fail("Database/WAL đã thay đổi trong bộ cài. Đã dừng an toàn.")

        export_dir.mkdir(parents=True, exist_ok=True)
        report = {
            "installed_at": dt.datetime.now().isoformat(timespec="seconds"),
            "title_internal": TITLE,
            "database_unchanged": True,
            "backup_dir": str(backup_dir),
            "changes": [
                "Bỏ số phiên bản khỏi giao diện sáp nhập.",
                "Chuẩn hóa tên: Sáp nhập trường / Bảng điều khiển sáp nhập toàn tỉnh / Sáp nhập phát sinh / Xem trước / Kết quả.",
                "Đổi thông báo kỹ thuật V4.3/V4.1 thành mô tả nghiệp vụ dễ hiểu.",
                "Giữ nguyên chức năng Đổi tên trường.",
                "Giữ nguyên luồng Sáp nhập phát sinh: Xã/phường -> Cấp học -> Năm hiệu lực -> Nguồn -> Đích.",
            ],
            "files": {rel: {"sha256": FINAL_HASHES[rel]} for rel in EMBEDDED_FILES},
        }
        report_path.write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8")
        print()
        print("=" * 104)
        print("CHUẨN HÓA GIAO DIỆN SÁP NHẬP - CÀI ĐẶT THÀNH CÔNG")
        print("Database: KHÔNG THAY ĐỔI")
        print("Đã bỏ số phiên bản khỏi giao diện sáp nhập.")
        print("Đổi tên trường: GIỮ NGUYÊN")
        print("Sáp nhập phát sinh: chỉ nằm trong Bảng điều khiển toàn tỉnh.")
        print("Luồng phát sinh: Xã/phường -> Cấp học -> Năm hiệu lực -> Nguồn -> Đích.")
        print(f"Backup mã nguồn: {backup_dir}")
        print(f"Báo cáo: {report_path}")
        print("=" * 104)
    except Exception as e:
        try:
            for rel in touched:
                bp = backup_dir / rel
                if bp.exists():
                    p = root / rel
                    p.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(bp, p)
        except Exception:
            pass
        print()
        print("=" * 104)
        print("DỪNG AN TOÀN - CHUẨN HÓA GIAO DIỆN SÁP NHẬP")
        print("Mã nguồn đã được khôi phục nếu đã chạm file.")
        print(f"Lỗi: {e}")
        print("Bộ cài KHÔNG thực hiện sáp nhập và KHÔNG chủ động ghi phocap.db.")
        print("=" * 104)
        if os.environ.get("PHOCAP_INSTALLER_DEBUG") == "1":
            traceback.print_exc()
        raise SystemExit(1)

if __name__ == "__main__":
    main()
